function withdrawAll() public {
    uint oCredit = credit[msg.sender];
    if (oCredit > 0) {
        balance -= oCredit;
        credit[msg.sender] = 0;
        (bool callResult, ) = msg.sender.call{value: 1}("");
        require(callResult);
    }
}

